   602→    pub fn check_and_set_reconstruction_started(
   603→        &self,
   604→        block_root: &Hash256,
   605→    ) -> ReconstructColumnsDecision<T::EthSpec> {
   606→        let mut write_lock = self.critical.write();
   607→        let Some(pending_components) = write_lock.get_mut(block_root) else {
   608→            // Block may have been imported as it does not exist in availability cache.
   609→            return ReconstructColumnsDecision::No("block already imported");
   610→        };
   611→
   612→        // If we're sampling all columns, it means we must be custodying all columns.
   613→        let total_column_count = T::EthSpec::number_of_columns();
   614→        let received_column_count = pending_components.verified_data_columns.len();
   615→
   616→        if pending_components.reconstruction_started {
   617→            return ReconstructColumnsDecision::No("already started");
   618→        }
   619→        if received_column_count >= total_column_count {
   620→            return ReconstructColumnsDecision::No("all columns received");
   621→        }
   622→        if received_column_count < total_column_count / 2 {
   623→            return ReconstructColumnsDecision::No("not enough columns");
